  assert(rgrid !== null, 'Infra: road generation must succeed');
  const roadCount = rgrid!.flat().filter((id) => id.startsWith('road_')).length;
  assert(roadCount > 1, 'Infra: road must extend beyond seed (got ' + roadCount + ')');
