    reg = R.setStoreQty(reg, SH.STOREHOUSE_STORE_ID, 'coal', coal, { type: 'loaded' }, { location: { ...SH.STOREHOUSE_APPROACH }, capacity: SH.STOREHOUSE_CAPACITY_COAL });
